.version 8.5
.target sm_120
.address_size 64

.visible .entry conv_transpose2d_fp16(
    .param .u64 conv_input_ptr,
    .param .u64 conv_weight_ptr,
    .param .u64 conv_output_ptr,
    .param .u32 conv_batch,
    .param .u32 conv_in_channels,
    .param .u32 conv_out_channels,
    .param .u32 conv_H_in,
    .param .u32 conv_W_in,
    .param .u32 conv_H_out,
    .param .u32 conv_W_out,
    .param .u32 conv_kH,
    .param .u32 conv_kW
)
{
    // ----------------------------------------------------------
    // Register declarations
    // ----------------------------------------------------------
    .reg .pred %p<13>;
    .reg .b32  %r<34>;
    .reg .b64  %rd<17>;
    .reg .f32  %f<5>;
    .reg .f16  %h<5>;

    // ----------------------------------------------------------
    // Load kernel parameters
    // ----------------------------------------------------------
    ld.param.u64 %rd1,  [conv_input_ptr];
    ld.param.u64 %rd2,  [conv_weight_ptr];
    ld.param.u64 %rd3,  [conv_output_ptr];
    ld.param.u32 %r1,   [conv_batch];
    ld.param.u32 %r2,   [conv_in_channels];
    ld.param.u32 %r3,   [conv_out_channels];
    ld.param.u32 %r4,   [conv_H_in];
    ld.param.u32 %r5,   [conv_W_in];
    ld.param.u32 %r6,   [conv_H_out];
    ld.param.u32 %r7,   [conv_W_out];
    ld.param.u32 %r8,   [conv_kH];
    ld.param.u32 %r9,   [conv_kW];

    // Convert generic pointers to global address space
    cvta.to.global.u64 %rd10, %rd1;   // input base
    cvta.to.global.u64 %rd11, %rd2;   // weight base
    cvta.to.global.u64 %rd12, %rd3;   // output base

    // ----------------------------------------------------------
    // Compute total number of output elements and flatten thread index
    // ----------------------------------------------------------
    mul.lo.u32 %r10, %r1, %r3;        // batch * out_channels
    mul.lo.u32 %r11, %r10, %r6;       // * H_out
    mul.lo.u32 %r12, %r11, %r7;       // * W_out  -> total

    mov.u32 %r13, %ctaid.x;
    mov.u32 %r14, %ntid.x;
    mov.u32 %r15, %tid.x;
    mad.lo.s32 %r16, %r13, %r14, %r15; // flat index

    setp.ge.u32 %p0, %r16, %r12;
    @%p0 bra $L_EXIT;

    // ----------------------------------------------------------
    // Decompose linear index into (b, oc, h_out, w_out)
    // ----------------------------------------------------------
    rem.u32 %r17, %r16, %r7;   // w_out
    div.u32 %r18, %r16, %r7;   // tmp = idx / W_out
    rem.u32 %r19, %r18, %r6;   // h_out
    div.u32 %r20, %r18, %r6;   // tmp = tmp / H_out
    rem.u32 %r21, %r20, %r3;   // oc
    div.u32 %r22, %r20, %r3;   // b

    // ----------------------------------------------------------
    // Accumulator (float32)
    // ----------------------------------------------------------
    mov.f32 %f0, 0.0;

    // ----------------------------------------------------------
    // Loop over input channels and kernel spatial dimensions
    // ----------------------------------------------------------
    mov.u32 %r23, 0;                 // c_in = 0
$L_LOOP_C_IN:
    setp.ge.u32 %p1, %r23, %r2;
    @%p1 bra $L_AFTER_C_IN;

    mov.u32 %r24, 0;                 // k_h = 0
$L_LOOP_KH:
    setp.ge.u32 %p2, %r24, %r8;
    @%p2 bra $L_AFTER_KH;

    mov.u32 %r25, 0;                 // k_w = 0
$L_LOOP_KW:
    setp.ge.u32 %p3, %r25, %r9;
    @%p3 bra $L_AFTER_KW;

    // Compute input coordinates
    sub.s32 %r26, %r19, %r24;   // h_in = h_out - k_h
    sub.s32 %r27, %r17, %r25;   // w_in = w_out - k_w

    // Bounds check for input coordinate
    setp.lt.s32 %p4, %r26, 0;
    setp.ge.s32 %p5, %r26, %r4;
    or.pred %p6, %p4, %p5;

    setp.lt.s32 %p7, %r27, 0;
    setp.ge.s32 %p8, %r27, %r5;
    or.pred %p9, %p7, %p8;

    or.pred %p10, %p6, %p9;
