    mul.lo.u32 %r28, %r22, %r2;          // b * in_channels
    add.u32 %r28, %r28, %r23;           // + c_in
    mul.lo.u32 %r28, %r28, %r4;          // * H_in
    add.u32 %r28, %r28, %r26;           // + h_in
    mul.lo.u32 %r28, %r28, %r5;          // * W_in
    add.u32 %r28, %r28, %r27;           // + w_in

