    mul.lo.u32 %r29, %r23, %r3;          // c_in * out_channels
    add.u32 %r29, %r29, %r21;           // + oc
    mul.lo.u32 %r29, %r29, %r8;          // * kH
    add.u32 %r29, %r29, %r24;           // + k_h
    mul.lo.u32 %r29, %r29, %r9;          // * kW
    add.u32 %r29, %r29, %r25;           // + k_w

    mul.wide.u32 %rd13, %r29, 2;
    add.u64 %rd14, %rd11, %rd13;
    ld.global.f16 %h1, [%rd14];
    cvt.f32.f16 %f2, %h1;

    // Accumulate
    fma.rn.f32 %f0, %f1, %f2, %f0;

$L_CONT_KW:
    add.u32 %r25, %r25, 1;
    bra $L_LOOP_KW;

$L_AFTER_KW:
    add.u32 %r24, %r24, 1;
    bra $L_LOOP_KH;

$L_AFTER_KH:
    add.u32 %r23, %r23, 1;
    bra $L_LOOP_C_IN;

$L_AFTER_C_IN:
    // ---------------------------------------------------------
    // Write output (convert back to fp16)
    // ---------------------------------------------------------
    mul.lo.u32 %r30, %r22, %r3;          // b * out_channels
    add.u32 %r30, %r30, %r21;           // + oc
    mul.lo.u32 %r30, %r30, %r6;          // * H_out
    add.u32 %r30, %r30, %r19;           // + h_out
    mul.lo.u32 %r30, %r30, %r7;          // * W_out
    add.u32 %r30, %r30, %r17;           // + w_out

    mul.wide.u32 %rd13, %r30, 2;
    add.u64 %rd14, %rd12, %rd13;
    cvt.rn.f16.f32 %h2, %f0;
    st.global.f16 [%rd14], %h2;

$L_EXIT:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        # Create a ConvTranspose2d to obtain the weight tensor (fp16)
        self.conv = nn.ConvTranspose2d(in_channels,
                                      out_channels,
                                      kernel_size=kernel_size,
                                      stride=stride,
                                      padding=padding,
                                      output_padding=output_padding,
                                      groups=groups,
                                      bias=bias).half()
        # Load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 tensor on correct device
        x = x.to(dtype=torch.float16, device=x.device)

